      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      real(wp) :: tmp1, tmp2

      stat = 0
      npt = state%npt
      if (state%ready < 1) then
         call fatal_error(error, "[nonlocal_pcm_mf_medium] call nonlocal_pcm_assemble first")
         return
      end if
      state%ready = 1

      state%eps_solute = eps_solute
      state%lam = lam
      state%eps_inf = eps_inf
      state%eps = eps
      state%op3%npt = 3*npt
      state%op3%npoint = npt
      state%op3%id = 3
      state%op3%points => state%r
      state%op3%r => state%r
      state%op3%n => state%n
      state%op3%k1 => state%k1
      state%op3%k2 => state%k2
      state%op3%xi => state%xi
      state%op3%F => state%F
      state%op3%a => state%a
      state%s5 = 1.0_wp/state%lam
      state%s6 = 1.0_wp/state%eps_inf
      state%s7 = state%s6*state%eps
      state%s8 = sqrt(state%s7)
      tmp1 = state%s5*state%s8
      state%s9 = tmp1**(2)
      state%op3%c1 = state%s9
      state%op3%c2 = state%s5
      state%op3%c3 = state%s8
      state%s16 = 1.0_wp/state%eps
      tmp2 = -state%s16
      state%s17 = state%s6 + tmp2
      state%s18 = state%eps_solute*state%s17
      state%op3%c4 = state%s18
      state%s20 = state%s6*state%eps_solute
      state%op3%c5 = state%s20
      state%s21 = state%s16*state%eps_inf
      state%op3%c6 = state%s21
      call state%solver%setup(state%op3, error)
      if (allocated(error)) return
      state%op4%npt = npt
      state%op4%npoint = npt
      state%op4%id = 4
      state%op4%points => state%r
      state%op4%r => state%r
      state%op4%xi => state%xi
      state%op4%F => state%F
      state%op4%a => state%a
      state%op4%c1 = state%s9
      state%op4%c2 = state%s5
      state%op4%c3 = state%s8
      call state%solver%setup(state%op4, error)
      if (allocated(error)) return
      state%s1 = 1.0_wp/state%eps_solute
      state%s22 = -state%s21
      state%s23 = 1.0_wp + state%s22
      state%s25 = -state%s18
      state%s27 = -state%s20
      state%s28 = 1.0_wp + state%s27
      state%s35 = 0.5_wp*state%s1
      state%s36 = (-6.283185307179586_wp)*state%s28
      state%s57 = state%lam**(-2)

      state%ready = 2
   end subroutine nonlocal_pcm_mf_medium

